from typing import Any, Dict, List


class Storage:
    def __init__(self) -> None:
        self._records: List[Dict[str, Any]] = []

    def append(self, record: Dict[str, Any]) -> None:
        self._records.append(dict(record))

    def all_records(self) -> List[Dict[str, Any]]:
        return [dict(r) for r in self._records]

    def records_for_request(self, request_id: str) -> List[Dict[str, Any]]:
        return [dict(r) for r in self._records if r.get("request_id") == request_id]

from typing import Any, Dict, Optional

from storage import Storage


class TransientError(Exception):
    pass


class Service:
    def __init__(self, storage: Storage) -> None:
        self.storage = storage
        self._should_fail_after_write: Dict[str, bool] = {}

    def enable_post_write_failure_once(self, request_id: str) -> None:
        self._should_fail_after_write[request_id] = True

    def process(self, request: Dict[str, Any]) -> Dict[str, Any]:
        attempts = 0
        last_error: Optional[Exception] = None

        while attempts < 2:
            try:
                return self._handle(dict(request))
            except TransientError as exc:
                attempts += 1
                last_error = exc

        if last_error is not None:
            raise last_error
        raise RuntimeError("unreachable")

    def _handle(self, request: Dict[str, Any]) -> Dict[str, Any]:
        logical_id = request["request_id"]
        payload = request["payload"]

        record = {
            "request_id": self._persistence_request_id(request),
            "logical_request_id": logical_id,
            "result": self._compute_result(payload),
        }
        self.storage.append(record)

        if self._should_fail_after_write.pop(logical_id, False):
            retry_request = self._prepare_retry_request(request)
            request.clear()
            request.update(retry_request)
            raise TransientError("temporary failure after write")

        return {"status": "ok", "logical_request_id": logical_id}

    def _compute_result(self, payload: Dict[str, Any]) -> str:
        amount = payload.get("amount", 0)
        return f"processed:{amount}"

    def _prepare_retry_request(self, request: Dict[str, Any]) -> Dict[str, Any]:
        retry_request = dict(request)
        retry_request["attempt"] = request.get("attempt", 0) + 1
        return retry_request

    def _persistence_request_id(self, request: Dict[str, Any]) -> str:
        base = request["request_id"]
        attempt = request.get("attempt", 0)
        return f"{base}:attempt-{attempt}"


def build_request(request_id: str, amount: int) -> Dict[str, Any]:
    return {
        "request_id": request_id,
        "payload": {"amount": amount},
    }


def build_service() -> Service:
    return Service(Storage())

from typing import Dict, Any


class User:
    def __init__(self, first: str, last: str) -> None:
        self.first = first
        self.last = last

        # Derived representations (multiple!)
        self.display_name = self._format_display()
        self._cached_profile = self._build_profile_cache()

    # --- Public read APIs ---

    def get_display_name(self) -> str:
        return self.display_name

    def get_profile(self) -> Dict[str, Any]:
        # Returns cached representation
        return dict(self._cached_profile)

    def serialize(self) -> Dict[str, Any]:
        # Mixed source: partly dynamic, partly cached
        return {
            "display": self.display_name,
            "profile": dict(self._cached_profile),
            "full": f"{self.first} {self.last}",
        }

    # --- Mutation ---

    def update_name(self, first: str, last: str) -> None:
        self.first = first
        self.last = last

        # BUG: only partially refresh derived state
        self.display_name = self._format_display()
        # self._cached_profile is NOT updated

    # --- Internal helpers ---

    def _format_display(self) -> str:
        return f"{self.first.capitalize()} {self.last.upper()}"

    def _build_profile_cache(self) -> Dict[str, Any]:
        return {
            "first": self.first,
            "last": self.last,
            "display": self._format_display(),
        }


def build_user(first: str, last: str) -> User:
    return User(first, last)

from typing import Dict, Any

# Shared nested mutable structure (BUG)
_SHARED_COMPAT: Dict[str, Any] = {
    "flags": {
        "force_fallback": False,
        "compat_mode": False,
    }
}


def attach_compatibility_context(ctx: Dict[str, Any]) -> Dict[str, Any]:
    # Reuses shared nested structure (aliasing across requests)
    ctx["compat"] = _SHARED_COMPAT

    # Mutate based on version
    version = ctx["resolved_version"]
    if version.startswith("legacy"):
        ctx["compat"]["flags"]["force_fallback"] = True
        ctx["compat"]["flags"]["compat_mode"] = True
    else:
        # Partial reset (BUG: not fully isolating state)
        ctx["compat"]["flags"]["compat_mode"] = False

    return ctx
